# 保留系统提示 + 最近的若干轮对话，使总 Token 不超预算
import tiktoken

enc = tiktoken.get_encoding("o200k_base")  # 估算用，精确值以模型官方计数为准

def n_tokens(msg):
    return len(enc.encode(msg["content"]))

def trim_history(messages, budget):
    """messages: [{'role':..., 'content':...}]，从最新往回保留"""
    kept, used = [], 0
    for msg in reversed(messages):
        cost = n_tokens(msg)
        if used + cost > budget:
            break
        kept.append(msg)
        used += cost
    return list(reversed(kept))

# 窗口 = 输入 + 输出：预算要扣掉给输出留的 max_tokens
history = [{"role": "user", "content": "..."}]
print(trim_history(history, budget=8000))

# 简单的规则路由：便宜模型兜底，复杂任务升级
# 模型名以供应商当前文档为准，建议放在配置文件而非写死
MODELS = {
    "fast":  "claude-haiku-4-5",    # 分类、抽取、短回复
    "smart": "claude-sonnet-4-5",   # 编码、分析、多步任务
}

def pick_model(task_type: str, input_tokens: int) -> str:
    if task_type in {"classify", "extract", "summarize_short"}:
        return MODELS["fast"]
    if task_type in {"code", "agent", "analysis"} or input_tokens > 20_000:
        return MODELS["smart"]
    return MODELS["fast"]

print(pick_model("classify", 300))   # -> fast 模型
print(pick_model("code", 5000))      # -> smart 模型

// 浏览器原生 fetch：获取数据并渲染到页面
async function loadTodos() {
  const list = document.querySelector("#todos");
  try {
    const res = await fetch("/api/todos");          // 请求后端接口
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const todos = await res.json();                 // 解析 JSON
    list.innerHTML = "";
    for (const t of todos) {
      const li = document.createElement("li");
      li.textContent = t.title;                     // 用 textContent 防 XSS
      list.appendChild(li);
    }
  } catch (err) {
    list.textContent = "加载失败，请稍后重试";       // 给用户可理解的反馈
    console.error(err);
  }
}

document.addEventListener("DOMContentLoaded", loadTodos);

# pip install fastapi uvicorn ；运行：uvicorn main:app --reload
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

app = FastAPI()
TODOS: dict[int, str] = {}          # 演示用内存存储，生产应换数据库

class TodoIn(BaseModel):
    title: str = Field(min_length=1, max_length=100)   # 自动参数校验

@app.post("/api/todos", status_code=201)
def create_todo(todo: TodoIn):
    new_id = len(TODOS) + 1
    TODOS[new_id] = todo.title
    return {"id": new_id, "title": todo.title}

@app.get("/api/todos/{todo_id}")
def get_todo(todo_id: int):
    if todo_id not in TODOS:
        raise HTTPException(status_code=404, detail="not found")
    return {"id": todo_id, "title": TODOS[todo_id]}

